{
  "findings": [
    {
      "check_id": "CKV_GCP_14",
      "title": "Cloud SQL automated backups are disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "HIGH",
      "explanation": "The instance has backup_configuration.enabled set to false, preventing automated recovery from data loss, corruption, or operational failure."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "Cloud SQL does not require encrypted connections",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "HIGH",
      "explanation": "The require_ssl setting is false, allowing database clients to connect without transport encryption and potentially expose credentials and data in transit."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "PostgreSQL lock-wait logging is disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The log_lock_waits database flag is set to off, reducing visibility into prolonged lock waits that may indicate availability or malicious activity."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Cloud SQL deletion protection is disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The instance explicitly disables deletion protection, increasing the risk of accidental database deletion through Terraform."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"metadata_database\" {\n  name                = \"digital-library-content-management-platform-db-metadata\"\n  database_version    = \"POSTGRES_14\"\n  region              = var.region\n  deletion_protection = true\n\n  settings {\n    tier = \"db-f1-micro\"\n\n    backup_configuration {\n      enabled = true\n    }\n\n    ip_configuration {\n      ipv4_enabled = true\n      require_ssl  = true\n    }\n\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n  }\n}\n",
  "fix_summary": "Enabled automated backups, required SSL for database connections, enabled PostgreSQL lock-wait logging, and turned on Terraform deletion protection. Existing resource structure and public-IP behavior were otherwise preserved."
}
